// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }

    function testFuzz_property(address actor, uint96 deposit) public {
        vm.assume(actor != address(0));
        uint256 amount = bound(uint256(deposit), 1, 1e23);

        vm.deal(actor, amount);

        vm.prank(actor);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        uint256 before = c.balances(actor);
        require(before == amount);

        bool ok;
        vm.prank(actor);
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.balances(actor) == 0);
        } else {
            assertTrue(ok == false ? c.balances(actor) == before : true);
        }
    }
}
